    def get_real_minute_kline_bk(self, symbol, include, fq=None, ex_info=None, frequency_int=1):
        start_date = datetime.datetime.now().strftime('%Y%m%d')
        end_date = start_date
        kline = self.get_kline_by_date_ndarray(symbol, start_date, end_date, frequency_int)
        if len(kline) > 0:
            kline['unlimited'] = 0
        if not fq is not None or ex_info is None:
            return kline
        else:
            names = list(kline.dtype.names[1:])
            bars_tmp = kline[names]
            index = kline['datetime']
            base_bars = np.empty(shape=(len(index), len(kline.dtype) - 1), dtype=np.float64)
            for i in range(len(index)):
                for j, name in enumerate(names):
                    base_bars[i][j] = bars_tmp[name][i]
            save_digits = 2
            if symbol[0] in ('1', '5'):
                save_digits = 3
            adjust_bars_tuple = CalExrights(base_bars, index, ex_info, fq, save_digits)
            adjust_bars = adjust_bars_tuple[0]
            adjust_bars.dtype = bars_tmp.dtype
            kline = np.empty(dtype=kline.dtype, shape=(len(index),))
            for i in range(len(index)):
                kline['datetime'][i] = index[i]
                for name in names:
                    kline[name][i] = adjust_bars[name][i]
            else:
                return kline
