        """
        获取逐笔行情
        """
        if symbols:
            if int(int(data_count) if 0 < int(data_count) <= 200 else 200):
                pass
            symbols = list(symbols)
            symbols = [str(symbols)]
            return_data = {}
            after_symbols = symbols.copy()
            while len(after_symbols) > 0:
                request_symbols = after_symbols[:50]
                after_symbols = after_symbols[50:]
                param = [data_type, request_symbols, str(search_direction), str(data_count), str(start_pos)]
                redata, flag = self.api_get_from_zeromq_by_counts(str(param), True)
                if redata is not None:
                    redata = redata.get('data').get(data_type)
                    for key, value in redata.items():
                        return_data[key] = value
                else:
                    system_log.debug('逐笔数据默认返回空值')
                    return redata
            try:
                if return_data != {}:
                    if individual_data_in_dict == '1':
                        return return_data
                    else:
                        data = {}
                        columns = return_data.get('fields')
                        columns_tmp = copy.deepcopy(columns)
                        float_fields = ['hq_px']
                        for i in float_fields:
                            if i in columns_tmp:
                                columns_tmp.remove(i)
                        df_list = []
                        python_version = get_python_version()
                        if python_version == '3.11':
                            for stock in symbols:
                                data_list = return_data.get(stock)
                                if not data_list:
                                    system_log.debug('当前代码%s返回逐笔数据为空' % stock)
                                    data_list = []
                                data_df = pd.DataFrame(data_list, columns=columns, index=list(range(data_count)))
                                data_df.insert(0, 'code', stock)
                                df_list.append(data_df)
                            else:
                                result = pd.concat(df_list)
                                result[columns_tmp] = result[columns_tmp].astype('int64', errors='ignore')
                                result[float_fields] = result[float_fields].astype('float', errors='ignore')
                        elif python_version == '3.5':
                            for stock in symbols:
                                data_list = return_data.get(stock)
                                if not data_list:
                                    system_log.debug('当前代码%s返回逐笔数据为空' % stock)
                                    data_list = []
                                data_df = pd.DataFrame(data_list, columns=columns)
                                data[stock] = data_df
                                data_df[columns_tmp] = data_df[columns_tmp].astype('int64', errors='ignore')
                                data_df[float_fields] = data_df[float_fields].astype('float', errors='ignore')
                            else:
                                returnPa = pd.Panel(data)
                                result = copy.deepcopy(returnPa)
                            return None
                        else:
                            system_log.error('获取python版本异常，返回dict类型')
                            return return_data
                        return result
                else:
                    system_log.debug('逐笔数据接口返回异常，内容为空')
                    return None
            except BaseException:
                system_log.debug('逐笔数据接口返回异常，错误信息：%s' % get_traceback_message())
                return None
