    def get_gear_price(self, sids=None):
        """
        获取档位行情
        """
        gear_price = {}
        if sids is None:
            return gear_price
        else:
            default_gear = {'bid_grp': {}, 'offer_grp': {}}
            if isinstance(sids, str):
                gear_price = default_gear
                sids_tmp = sids.replace('XSHG', 'SS').replace('XSHE', 'SZ')
                symbol_data = self.imagedata.get(sids_tmp)
                if symbol_data is not None:
                    gear_price['bid_grp'] = symbol_data.get('bid_grp')
                    gear_price['offer_grp'] = symbol_data.get('offer_grp')
                else:
                    system_log.debug(_('当前股票代码{}无档位行情，默认返回空').format(sids))
            elif isinstance(sids, list):
                if len(sids) == 1:
                    sids = sids[-1]
                    gear_price = default_gear
                    sids_tmp = sids.replace('XSHG', 'SS').replace('XSHE', 'SZ')
                    symbol_data = self.imagedata.get(sids_tmp)
                    if symbol_data is not None:
                        gear_price['bid_grp'] = symbol_data.get('bid_grp')
                        gear_price['offer_grp'] = symbol_data.get('offer_grp')
                    else:
                        system_log.debug(_('当前股票代码{}无档位行情，默认返回空').format(sids))
                else:
                    for sid in sids:
                        sid_tmp = sid.replace('XSHG', 'SS').replace('XSHE', 'SZ')
                        symbol_data = self.imagedata.get(sid_tmp)
                        if symbol_data is not None:
                            gear_price[sid] = {}
                            gear_price[sid]['bid_grp'] = symbol_data.get('bid_grp')
                            gear_price[sid]['offer_grp'] = symbol_data.get('offer_grp')
                            continue
                        gear_price[sid] = default_gear
                        system_log.debug(_('当前股票代码{}无档位行情，默认返回空').format(sid))
                        continue
            return gear_price
